<template><AccountShell title="اعلان‌ها" description="پیام‌های حساب، آگهی، جست‌وجو و امنیت"><template #action><button class="button" type="button" @click="readAll">خواندن همه</button></template><UiState v-if="pending" kind="loading" title="در حال دریافت اعلان‌ها" description="چند لحظه صبر کنید."/><div v-else class="notification-list"><NotificationItem v-for="item in items" :key="item.id" :item="item" @read="markRead" @archive="archive"/><UiState v-if="!items.length" kind="empty" title="اعلانی ندارید" description="رویدادهای مهم هفت‌سو اینجا نمایش داده می‌شوند."/></div></AccountShell></template>
